extra=(ROOT/'input/additional-nasai2412-originals.jsonl').read_bytes();assert sha(extra)=='a2036f3de875c0b2ddefcc172bcc00a9367ac923afd72186970954d5916b941b'
sources={r['collection']+':'+r['number']:r for r in map(json.loads,cb.splitlines())};assert set(sources)==set(NOTES) and len(sources)==23
entries=json.loads((EVID/'held-state-entries.json').read_bytes());manifest=json.loads((EVID/'evidence-manifest.json').read_bytes());assert manifest['saved_head']==PIN
proof=[]
for key,r in sources.items():
    checked=[]
    for kind,d in [('raw',r['snapshot']),('parsed',entries[key]['parsed'])]:
        b=(EVID/'sources'/d['path']).read_bytes();authority=manifest['files'][d['path']]
        g=hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest();assert sha(b)==authority.get('stored_sha256',authority['sha256']) and g==authority['git_blob_sha1']
        plain=importer.checked_bytes(EVID/'sources',d)
        if kind=='raw':
            obj,cite=importer.parse_record(plain,r['collection'],r['number']);assert obj==r['source_record'] and cite==r['source_reference_verbatim']
        else:
            parsed=json.loads(plain)
            for k in ['collection','number','source_record','source_reference_verbatim','snapshot']:assert parsed[k]==r[k]
        checked.append({'kind':kind,'path':d['path'],'stored_bytes':len(b),'stored_sha256':sha(b),'git_blob_sha1':g,'plain_sha256':sha(plain)})
    proof.append({'id':'deenhindi-'+key,'files':checked,'raw_reparse_exact':True,'source_record_sha256':sha(importer.json_bytes(r['source_record']))})
fields=[]
for f in [json.loads(x) for raw in [base,extra] for x in raw.splitlines()]:
    key=f['collection']+':'+f['number'];text=f['text'];assert text==sources[key]['source_record'][f['source_field']] and sha(text.encode())==f['text_sha256']
    note=NOTES[key][0]+(' '+NOTES[key][1] if f['language']=='ur' else '')
    fields.append({'id':f['occurrence_id'],'language':f['language'],'source_field':f['source_field'],'text':text,'sha256':sha(text.encode()),'characters':len(text),'utf8_bytes':len(text.encode()),'complete_field_read':True,'reading_note':note})
assert len(fields)==49 and sum(f['characters'] for f in fields)==29579
